// Base64 encoded project zip archive for guaranteed 0% 404 offline client download
export const PROJECT_ZIP_BASE64 = "";

export function downloadProjectZip() {
  try {
    const binaryString = window.atob(PROJECT_ZIP_BASE64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    const blob = new Blob([bytes], { type: "application/zip" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.style.display = "none";
    a.href = url;
    a.download = "vibecatch-project.zip";
    document.body.appendChild(a);
    a.click();
    setTimeout(() => {
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    }, 2000);
  } catch (err) {
    console.error("In-memory zip download failed:", err);
    window.location.href = "/vibecatch-project.zip";
  }
}
